export type GameSourceType = 'approved-embed' | 'external-link' | 'self-hosted' | 'placeholder'

export type Game = {
  slug: string
  title: string
  genre: string
  description: string
  tags: string[]
  thumbnailUrl: string
  bannerUrl: string
  playUrl: string
  launchMode?: 'iframe' | 'new-tab'
  sourceType: GameSourceType
  provider: string
  licenseUrl: string | null
  featured: boolean
  multiplayer: boolean
  addedAt?: string
  accent: string
  secondaryAccent: string
  symbol: string
}

type HostedGame = Omit<Game, 'thumbnailUrl' | 'bannerUrl' | 'sourceType'> & { thumbnailExtension?: 'png' | 'jpg' }

function hostedGame(game: HostedGame, sourceType: GameSourceType = 'approved-embed'): Game {
  const { thumbnailExtension = 'png', ...details } = game
  const thumbnailUrl = `/game-thumbnails/${game.slug}.${thumbnailExtension}`

  return {
    ...details,
    thumbnailUrl,
    bannerUrl: thumbnailUrl,
    sourceType,
    launchMode: details.launchMode ?? (sourceType === 'external-link' ? 'new-tab' : 'iframe'),
  }
}


function externalGame(game: Omit<Game, 'sourceType'>): Game { return { ...game, sourceType: 'approved-embed', launchMode: 'iframe' } }



type CatalogGameInput = { slug: string; title: string; genre: string; playUrl: string; thumbnailUrl: string; provider: string; source: string; accent: string; secondaryAccent: string; symbol: string }
function catalogGame(item: CatalogGameInput): Game {
  return { ...item, bannerUrl: item.thumbnailUrl, description: `${item.title} from the ${item.provider} catalog.`, tags: [item.genre, item.provider, 'Catalog'], sourceType: 'approved-embed', launchMode: 'iframe', licenseUrl: item.source, featured: false, multiplayer: false }
}
